# region src/Private/Common.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

$script:WinToolPublishedUrl = "https://raw.githubusercontent.com/Hinrikao/WinTool/main/wintool.ps1"
$script:WinToolProfileBegin = "# >>> WinTool terminal setup >>>"
$script:WinToolProfileEnd = "# <<< WinTool terminal setup <<<"

if ([string]::IsNullOrWhiteSpace($script:WinToolVersion)) {
    $script:WinToolVersion = "1.0.0"
}

function Get-WinToolNote {
    param(
        $Object,
        [Parameter(Mandatory = $true)][string]$Name,
        $Default = $null
    )
    if ($null -eq $Object) {
        return $Default
    }
    $property = $Object.PSObject.Properties[$Name]
    if ($null -eq $property -or $null -eq $property.Value) {
        return $Default
    }
    return $property.Value
}

function Test-WinToolWindows {
    return ($env:OS -eq "Windows_NT")
}

function Test-WinToolTextMatch {
    param(
        [string]$Haystack,
        [string]$Query
    )
    if ([string]::IsNullOrWhiteSpace($Query)) {
        return $true
    }
    if ([string]::IsNullOrWhiteSpace($Haystack)) {
        return $false
    }
    return ($Haystack.IndexOf($Query.Trim(), [System.StringComparison]::OrdinalIgnoreCase) -ge 0)
}

function Get-WinToolPayloadText {
    param(
        [Parameter(Mandatory = $true)][string]$Name
    )
    $embedded = $script:WinToolEmbedded
    if ($null -ne $embedded -and $embedded.ContainsKey($Name)) {
        $clean = ([string]$embedded[$Name]) -replace '\s', ''
        $bytes = [Convert]::FromBase64String($clean)
        return [System.Text.Encoding]::UTF8.GetString($bytes)
    }

    if ([string]::IsNullOrWhiteSpace($script:WinToolRoot)) {
        throw "WinTool payload '$Name' is not embedded and no source folder is set."
    }

    $relative = @{
        Apps = "data/apps.json"
        Tweaks = "data/tweaks.json"
        Terminal = "data/terminal.json"
        Updates = "data/updates.json"
        Xaml = "assets/MainWindow.xaml"
        Wsl = "data/wsl-setup.sh"
    }
    if (-not $relative.ContainsKey($Name)) {
        throw "Unknown WinTool payload '$Name'."
    }

    $path = Join-Path $script:WinToolRoot $relative[$Name]
    return [System.IO.File]::ReadAllText($path)
}

function Get-WinToolLogPath {
    if (-not [string]::IsNullOrWhiteSpace($script:WinToolLogFile)) {
        return $script:WinToolLogFile
    }
    if ([string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        return $null
    }
    $directory = Join-Path $env:LOCALAPPDATA "WinTool/logs"
    if (-not (Test-Path -LiteralPath $directory)) {
        New-Item -ItemType Directory -Path $directory -Force | Out-Null
    }
    $name = "wintool-" + (Get-Date -Format "yyyyMMdd-HHmmss") + ".log"
    $script:WinToolLogFile = Join-Path $directory $name
    return $script:WinToolLogFile
}

function Add-WinToolLogLine {
    param(
        [Parameter(Mandatory = $true)][string]$Line
    )
    $path = Get-WinToolLogPath
    if (-not [string]::IsNullOrWhiteSpace($path)) {
        try {
            Add-Content -LiteralPath $path -Value $Line -Encoding UTF8
        }
        catch {
            $null = $_.Exception.Message
        }
    }

    if ($null -eq $script:WinToolLogBox) {
        Write-Host $Line
        return
    }

    $box = $script:WinToolLogBox
    $write = {
        $box.AppendText($Line + [Environment]::NewLine)
        $box.ScrollToEnd()
    }.GetNewClosure()

    if ($box.Dispatcher.CheckAccess()) {
        & $write
    }
    else {
        $box.Dispatcher.BeginInvoke([System.Action]$write) | Out-Null
    }
}

function Write-WinToolLog {
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Message,
        [ValidateSet("info", "ok", "warn", "error")]
        [string]$Level = "info"
    )
    if ([string]::IsNullOrWhiteSpace($Message)) {
        return
    }
    $prefix = "INFO"
    if ($Level -eq "ok") { $prefix = " OK " }
    elseif ($Level -eq "warn") { $prefix = "WARN" }
    elseif ($Level -eq "error") { $prefix = "FAIL" }
    $stamp = Get-Date -Format "HH:mm:ss"
    $line = "{0}  {1}  {2}" -f $stamp, $prefix, $Message
    Add-WinToolLogLine -Line $line
}

function ConvertTo-WinToolArgumentLine {
    param(
        [string[]]$ArgumentList
    )
    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($argument in @($ArgumentList)) {
        if ($null -eq $argument) {
            continue
        }
        $text = [string]$argument
        if ($text -match '[\s"]') {
            $escaped = $text.Replace('"', '\"')
            $parts.Add('"' + $escaped + '"')
        }
        else {
            $parts.Add($text)
        }
    }
    return ($parts -join " ")
}

function Write-WinToolUtf8File {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Text
    )
    $encoding = New-Object System.Text.UTF8Encoding $false
    [System.IO.File]::WriteAllText($Path, $Text, $encoding)
}
# endregion

# region src/Private/Json.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function ConvertTo-WinToolJsonString {
    param(
        [AllowNull()][string]$Text
    )
    if ($null -eq $Text) {
        return "null"
    }
    $builder = New-Object System.Text.StringBuilder
    [void]$builder.Append('"')
    foreach ($char in $Text.ToCharArray()) {
        $code = [int]$char
        if ($code -eq 34) {
            [void]$builder.Append('\"')
        }
        elseif ($code -eq 92) {
            [void]$builder.Append('\\')
        }
        elseif ($code -eq 8) {
            [void]$builder.Append('\b')
        }
        elseif ($code -eq 12) {
            [void]$builder.Append('\f')
        }
        elseif ($code -eq 10) {
            [void]$builder.Append('\n')
        }
        elseif ($code -eq 13) {
            [void]$builder.Append('\r')
        }
        elseif ($code -eq 9) {
            [void]$builder.Append('\t')
        }
        elseif ($code -lt 32) {
            [void]$builder.Append('\u')
            [void]$builder.Append($code.ToString("x4"))
        }
        else {
            [void]$builder.Append($char)
        }
    }
    [void]$builder.Append('"')
    return $builder.ToString()
}

function ConvertTo-WinToolJsonText {
    param(
        $Value,
        [int]$Indent = 0
    )
    $pad = " " * ($Indent * 2)
    $next = $Indent + 1
    $inner = " " * ($next * 2)

    if ($null -eq $Value) {
        return "null"
    }
    if ($Value -is [string]) {
        return (ConvertTo-WinToolJsonString -Text $Value)
    }
    if ($Value -is [bool]) {
        if ($Value) { return "true" }
        return "false"
    }
    if ($Value -is [ValueType]) {
        return [Convert]::ToString($Value, [System.Globalization.CultureInfo]::InvariantCulture)
    }

    $isCustom = $Value -is [System.Management.Automation.PSCustomObject]
    if (-not $isCustom -and $Value -is [System.Collections.IDictionary]) {
        $names = @($Value.Keys)
        if ($names.Count -eq 0) {
            return "{}"
        }
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($name in $names) {
            $encoded = ConvertTo-WinToolJsonString -Text ([string]$name)
            $child = ConvertTo-WinToolJsonText -Value $Value[$name] -Indent $next
            $lines.Add($inner + $encoded + ": " + $child)
        }
        return "{`n" + ($lines -join ",`n") + "`n" + $pad + "}"
    }

    if (-not $isCustom -and $Value -is [System.Collections.IEnumerable]) {
        $items = @($Value)
        if ($items.Count -eq 0) {
            return "[]"
        }
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($item in $items) {
            $lines.Add($inner + (ConvertTo-WinToolJsonText -Value $item -Indent $next))
        }
        return "[`n" + ($lines -join ",`n") + "`n" + $pad + "]"
    }

    $properties = @($Value.PSObject.Properties)
    if ($properties.Count -eq 0) {
        return "{}"
    }
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($property in $properties) {
        $encoded = ConvertTo-WinToolJsonString -Text ([string]$property.Name)
        $child = ConvertTo-WinToolJsonText -Value $property.Value -Indent $next
        $lines.Add($inner + $encoded + ": " + $child)
    }
    return "{`n" + ($lines -join ",`n") + "`n" + $pad + "}"
}

function ConvertTo-WinToolPlainJson {
    param(
        [AllowEmptyString()][string]$Text
    )
    if ([string]::IsNullOrEmpty($Text)) {
        return $Text
    }
    $builder = New-Object System.Text.StringBuilder
    $chars = $Text.ToCharArray()
    $inString = $false
    $escape = $false
    $index = 0
    while ($index -lt $chars.Length) {
        $char = $chars[$index]
        if ($inString) {
            [void]$builder.Append($char)
            if ($escape) {
                $escape = $false
            }
            elseif ($char -eq '\') {
                $escape = $true
            }
            elseif ($char -eq '"') {
                $inString = $false
            }
            $index++
            continue
        }
        if ($char -eq '"') {
            $inString = $true
            [void]$builder.Append($char)
            $index++
            continue
        }
        if ($char -eq '/' -and ($index + 1) -lt $chars.Length) {
            $next = $chars[$index + 1]
            if ($next -eq '/') {
                $index += 2
                while ($index -lt $chars.Length -and $chars[$index] -ne "`n") {
                    $index++
                }
                continue
            }
            if ($next -eq '*') {
                $index += 2
                while (($index + 1) -lt $chars.Length -and -not ($chars[$index] -eq '*' -and $chars[$index + 1] -eq '/')) {
                    $index++
                }
                if (($index + 1) -lt $chars.Length) {
                    $index += 2
                }
                else {
                    $index = $chars.Length
                }
                continue
            }
        }
        [void]$builder.Append($char)
        $index++
    }
    return [regex]::Replace($builder.ToString(), ',(?=\s*[}\]])', '')
}

function ConvertFrom-WinToolJsonText {
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Text
    )
    $plain = ConvertTo-WinToolPlainJson -Text $Text
    if ([string]::IsNullOrWhiteSpace($plain)) {
        throw "The JSON text was empty."
    }
    return ($plain | ConvertFrom-Json)
}

function Read-WinToolJsonFile {
    param(
        [Parameter(Mandatory = $true)][string]$Path
    )
    $text = [System.IO.File]::ReadAllText($Path)
    return (ConvertFrom-WinToolJsonText -Text $text)
}

function Write-WinToolJsonFile {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [Parameter(Mandatory = $true)]$Value
    )
    $json = ConvertTo-WinToolJsonText -Value $Value
    Write-WinToolUtf8File -Path $Path -Text ($json + "`n")
}
# endregion

# region src/Private/Catalog.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Get-WinToolAppCatalog {
    return (ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "Apps"))
}

function Get-WinToolTweakCatalog {
    return (ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "Tweaks"))
}

function Get-WinToolTerminalCatalog {
    return (ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "Terminal"))
}

function Get-WinToolUpdateCatalog {
    return (ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name "Updates"))
}

function Get-WinToolPresetTweak {
    param(
        [Parameter(Mandatory = $true)]$Catalog,
        [Parameter(Mandatory = $true)][string]$PresetId
    )
    $matched = New-Object System.Collections.Generic.List[object]
    foreach ($tweak in @($Catalog.tweaks)) {
        $presets = @(Get-WinToolNote -Object $tweak -Name "presets" -Default @())
        if ($presets -contains $PresetId) {
            $matched.Add($tweak)
        }
    }
    return $matched.ToArray()
}

function Test-WinToolWingetId {
    param(
        [string]$Id
    )
    if ([string]::IsNullOrWhiteSpace($Id)) {
        return $false
    }
    return ($Id -match '^[A-Za-z0-9][A-Za-z0-9._+-]*\.[A-Za-z0-9][A-Za-z0-9._+-]*$')
}

function Add-WinToolDataError {
    param(
        $Errors,
        [string]$Message
    )
    $Errors.Add($Message)
}

function Test-WinToolRegistryAction {
    param(
        $Action,
        [string]$Label,
        $Errors
    )
    $type = [string](Get-WinToolNote -Object $Action -Name "type" -Default "")
    if ($type -eq "group") {
        $nested = @(Get-WinToolNote -Object $Action -Name "actions" -Default @())
        if ($nested.Count -eq 0) {
            Add-WinToolDataError -Errors $Errors -Message "$Label group has no actions."
        }
        foreach ($child in $nested) {
            Test-WinToolRegistryAction -Action $child -Label $Label -Errors $Errors
        }
        return
    }
    if ($type -eq "registry" -or $type -eq "registry-remove") {
        $entries = @(Get-WinToolNote -Object $Action -Name "entries" -Default @())
        if ($entries.Count -eq 0) {
            Add-WinToolDataError -Errors $Errors -Message "$Label has no registry entries."
        }
        foreach ($entry in $entries) {
            $path = [string](Get-WinToolNote -Object $entry -Name "path" -Default "")
            if ($path -notmatch '^(HKCU|HKLM):\\') {
                Add-WinToolDataError -Errors $Errors -Message "$Label has a registry path that is not HKCU or HKLM."
            }
            $nameProperty = $entry.PSObject.Properties["name"]
            if ($null -eq $nameProperty) {
                Add-WinToolDataError -Errors $Errors -Message "$Label is missing a registry value name."
            }
            if ($type -eq "registry") {
                $kind = [string](Get-WinToolNote -Object $entry -Name "kind" -Default "")
                if (@("DWord", "QWord", "String", "ExpandString", "MultiString") -notcontains $kind) {
                    Add-WinToolDataError -Errors $Errors -Message "$Label uses an unknown registry kind '$kind'."
                }
                if ($null -eq $entry.PSObject.Properties["value"]) {
                    Add-WinToolDataError -Errors $Errors -Message "$Label is missing a registry value."
                }
            }
        }
        return
    }
    if ($type -eq "registry-key") {
        $path = [string](Get-WinToolNote -Object $Action -Name "path" -Default "")
        $operation = [string](Get-WinToolNote -Object $Action -Name "operation" -Default "")
        if ($path -notmatch '^(HKCU|HKLM):\\') {
            Add-WinToolDataError -Errors $Errors -Message "$Label has a registry key outside HKCU or HKLM."
        }
        if (@("add", "remove") -notcontains $operation) {
            Add-WinToolDataError -Errors $Errors -Message "$Label registry key operation must be add or remove."
        }
        return
    }
    if ($type -eq "service") {
        $name = [string](Get-WinToolNote -Object $Action -Name "name" -Default "")
        $startup = [string](Get-WinToolNote -Object $Action -Name "startupType" -Default "")
        if ([string]::IsNullOrWhiteSpace($name)) {
            Add-WinToolDataError -Errors $Errors -Message "$Label is missing a service name."
        }
        if (@("Automatic", "Manual", "Disabled") -notcontains $startup) {
            Add-WinToolDataError -Errors $Errors -Message "$Label has an unknown service startup type."
        }
        return
    }
    if ($type -eq "scheduled-task") {
        $taskName = [string](Get-WinToolNote -Object $Action -Name "taskName" -Default "")
        $taskPath = [string](Get-WinToolNote -Object $Action -Name "taskPath" -Default "")
        $state = [string](Get-WinToolNote -Object $Action -Name "state" -Default "")
        if ([string]::IsNullOrWhiteSpace($taskName) -or [string]::IsNullOrWhiteSpace($taskPath)) {
            Add-WinToolDataError -Errors $Errors -Message "$Label is missing a scheduled task name or path."
        }
        if (@("Enabled", "Disabled") -notcontains $state) {
            Add-WinToolDataError -Errors $Errors -Message "$Label has an unknown scheduled task state."
        }
        return
    }
    if ($type -eq "appx") {
        $packages = @(Get-WinToolNote -Object $Action -Name "packages" -Default @())
        if ($packages.Count -eq 0) {
            Add-WinToolDataError -Errors $Errors -Message "$Label does not list any inbox apps."
        }
        foreach ($package in $packages) {
            if ([string]$package -match 'WindowsStore|SecHealthUI') {
                Add-WinToolDataError -Errors $Errors -Message "$Label tries to remove a protected inbox app."
            }
        }
        return
    }
    if ($type -eq "appx-restore") {
        return
    }
    Add-WinToolDataError -Errors $Errors -Message "$Label uses an unknown action type '$type'."
}

function Test-WinToolDataFile {
    $errors = New-Object System.Collections.Generic.List[string]
    $apps = Get-WinToolAppCatalog
    $tweaks = Get-WinToolTweakCatalog
    $terminal = Get-WinToolTerminalCatalog
    $updates = Get-WinToolUpdateCatalog

    if ([int](Get-WinToolNote -Object $apps -Name "schemaVersion" -Default 0) -ne 1) {
        Add-WinToolDataError -Errors $errors -Message "apps.json schemaVersion must be 1."
    }
    if ([int](Get-WinToolNote -Object $tweaks -Name "schemaVersion" -Default 0) -ne 1) {
        Add-WinToolDataError -Errors $errors -Message "tweaks.json schemaVersion must be 1."
    }
    if ([int](Get-WinToolNote -Object $terminal -Name "schemaVersion" -Default 0) -ne 1) {
        Add-WinToolDataError -Errors $errors -Message "terminal.json schemaVersion must be 1."
    }
    if ([int](Get-WinToolNote -Object $updates -Name "schemaVersion" -Default 0) -ne 1) {
        Add-WinToolDataError -Errors $errors -Message "updates.json schemaVersion must be 1."
    }

    $appIds = @{}
    $categories = @(Get-WinToolNote -Object $apps -Name "categories" -Default @())
    if ($categories.Count -eq 0) {
        Add-WinToolDataError -Errors $errors -Message "apps.json has no categories."
    }
    foreach ($category in $categories) {
        $categoryId = [string](Get-WinToolNote -Object $category -Name "id" -Default "")
        $categoryName = [string](Get-WinToolNote -Object $category -Name "name" -Default "")
        if ([string]::IsNullOrWhiteSpace($categoryId) -or [string]::IsNullOrWhiteSpace($categoryName)) {
            Add-WinToolDataError -Errors $errors -Message "A category is missing an id or name."
        }
        foreach ($app in @(Get-WinToolNote -Object $category -Name "apps" -Default @())) {
            $id = [string](Get-WinToolNote -Object $app -Name "id" -Default "")
            $name = [string](Get-WinToolNote -Object $app -Name "name" -Default "")
            $description = [string](Get-WinToolNote -Object $app -Name "description" -Default "")
            $wingetId = [string](Get-WinToolNote -Object $app -Name "wingetId" -Default "")
            if ([string]::IsNullOrWhiteSpace($id) -or [string]::IsNullOrWhiteSpace($name) -or [string]::IsNullOrWhiteSpace($description)) {
                Add-WinToolDataError -Errors $errors -Message "An app in '$categoryId' is missing an id, name, or description."
            }
            if ($appIds.ContainsKey($id)) {
                Add-WinToolDataError -Errors $errors -Message "Duplicate app id '$id'."
            }
            else {
                $appIds[$id] = $true
            }
            if (-not (Test-WinToolWingetId -Id $wingetId)) {
                Add-WinToolDataError -Errors $errors -Message "App '$id' has an unexpected winget id '$wingetId'."
            }
            $scope = [string](Get-WinToolNote -Object $app -Name "scope" -Default "")
            if (-not [string]::IsNullOrWhiteSpace($scope) -and @("user", "machine") -notcontains $scope) {
                Add-WinToolDataError -Errors $errors -Message "App '$id' has an unknown scope."
            }
        }
    }

    $presetIds = @{}
    foreach ($preset in @(Get-WinToolNote -Object $tweaks -Name "presets" -Default @())) {
        $presetId = [string](Get-WinToolNote -Object $preset -Name "id" -Default "")
        $presetName = [string](Get-WinToolNote -Object $preset -Name "name" -Default "")
        if ([string]::IsNullOrWhiteSpace($presetId) -or [string]::IsNullOrWhiteSpace($presetName)) {
            Add-WinToolDataError -Errors $errors -Message "A preset is missing an id or name."
            continue
        }
        if ($presetIds.ContainsKey($presetId)) {
            Add-WinToolDataError -Errors $errors -Message "Duplicate preset id '$presetId'."
        }
        $presetIds[$presetId] = $true
    }

    $tweakIds = @{}
    foreach ($tweak in @(Get-WinToolNote -Object $tweaks -Name "tweaks" -Default @())) {
        $id = [string](Get-WinToolNote -Object $tweak -Name "id" -Default "")
        $name = [string](Get-WinToolNote -Object $tweak -Name "name" -Default "")
        $description = [string](Get-WinToolNote -Object $tweak -Name "description" -Default "")
        $risk = [string](Get-WinToolNote -Object $tweak -Name "risk" -Default "")
        $refresh = [string](Get-WinToolNote -Object $tweak -Name "refresh" -Default "")
        if ([string]::IsNullOrWhiteSpace($id) -or [string]::IsNullOrWhiteSpace($name) -or [string]::IsNullOrWhiteSpace($description)) {
            Add-WinToolDataError -Errors $errors -Message "A tweak is missing an id, name, or description."
        }
        if ($tweakIds.ContainsKey($id)) {
            Add-WinToolDataError -Errors $errors -Message "Duplicate tweak id '$id'."
        }
        else {
            $tweakIds[$id] = $true
        }
        if (@("safe", "caution") -notcontains $risk) {
            Add-WinToolDataError -Errors $errors -Message "Tweak '$id' has an unknown risk."
        }
        if (@("none", "theme", "explorer") -notcontains $refresh) {
            Add-WinToolDataError -Errors $errors -Message "Tweak '$id' has an unknown refresh value."
        }
        foreach ($presetId in @(Get-WinToolNote -Object $tweak -Name "presets" -Default @())) {
            if (-not $presetIds.ContainsKey([string]$presetId)) {
                Add-WinToolDataError -Errors $errors -Message "Tweak '$id' uses an unknown preset '$presetId'."
            }
        }
        $apply = Get-WinToolNote -Object $tweak -Name "apply"
        $undo = Get-WinToolNote -Object $tweak -Name "undo"
        if ($null -eq $apply -or $null -eq $undo) {
            Add-WinToolDataError -Errors $errors -Message "Tweak '$id' needs both apply and undo."
            continue
        }
        Test-WinToolRegistryAction -Action $apply -Label "Tweak '$id' apply" -Errors $errors
        Test-WinToolRegistryAction -Action $undo -Label "Tweak '$id' undo" -Errors $errors
    }

    foreach ($prompt in @(Get-WinToolNote -Object $terminal -Name "prompts" -Default @())) {
        $id = [string](Get-WinToolNote -Object $prompt -Name "id" -Default "")
        $wingetId = [string](Get-WinToolNote -Object $prompt -Name "wingetId" -Default "")
        if ([string]::IsNullOrWhiteSpace($id) -or -not (Test-WinToolWingetId -Id $wingetId)) {
            Add-WinToolDataError -Errors $errors -Message "A terminal prompt is missing an id or winget id."
        }
    }
    foreach ($font in @(Get-WinToolNote -Object $terminal -Name "fonts" -Default @())) {
        $id = [string](Get-WinToolNote -Object $font -Name "id" -Default "")
        $face = [string](Get-WinToolNote -Object $font -Name "face" -Default "")
        $match = [string](Get-WinToolNote -Object $font -Name "match" -Default "")
        $wingetId = [string](Get-WinToolNote -Object $font -Name "wingetId" -Default "")
        if ([string]::IsNullOrWhiteSpace($id) -or [string]::IsNullOrWhiteSpace($face) -or [string]::IsNullOrWhiteSpace($match)) {
            Add-WinToolDataError -Errors $errors -Message "A terminal font is missing an id, face, or match token."
        }
        if (-not (Test-WinToolWingetId -Id $wingetId)) {
            Add-WinToolDataError -Errors $errors -Message "Terminal font '$id' has an unexpected winget id."
        }
    }

    foreach ($vendor in @(Get-WinToolNote -Object $updates -Name "vendors" -Default @())) {
        $id = [string](Get-WinToolNote -Object $vendor -Name "id" -Default "")
        $url = [string](Get-WinToolNote -Object $vendor -Name "url" -Default "")
        $match = @(Get-WinToolNote -Object $vendor -Name "match" -Default @())
        if ([string]::IsNullOrWhiteSpace($id) -or $match.Count -eq 0) {
            Add-WinToolDataError -Errors $errors -Message "A graphics vendor is missing an id or match list."
        }
        if ($url -notmatch '^https://') {
            Add-WinToolDataError -Errors $errors -Message "Vendor '$id' must use an https link."
        }
    }

    return $errors.ToArray()
}
# endregion

# region src/Private/Winget.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# winget returns 0x8A15002B when the package is already installed and no upgrade applies.
$script:WinToolWingetAlreadyInstalled = -1978335189

function Sync-WinToolProcessPath {
    if (-not (Test-WinToolWindows)) {
        return
    }
    $machine = [Environment]::GetEnvironmentVariable("Path", "Machine")
    $user = [Environment]::GetEnvironmentVariable("Path", "User")
    if ([string]::IsNullOrWhiteSpace($machine)) {
        $env:Path = [string]$user
        return
    }
    if ([string]::IsNullOrWhiteSpace($user)) {
        $env:Path = [string]$machine
        return
    }
    $env:Path = "$machine;$user"
}

function Get-WinToolWingetPath {
    if (-not (Test-WinToolWindows)) {
        return $null
    }
    Sync-WinToolProcessPath
    $command = Get-Command -Name "winget.exe" -ErrorAction SilentlyContinue
    if ($null -ne $command -and -not [string]::IsNullOrWhiteSpace([string]$command.Source)) {
        return [string]$command.Source
    }
    $fallback = Join-Path $env:LOCALAPPDATA "Microsoft/WindowsApps/winget.exe"
    if (Test-Path -LiteralPath $fallback) {
        return $fallback
    }
    return $null
}

function Get-WinToolWingetArgument {
    param(
        [Parameter(Mandatory = $true)][string]$Id,
        [string]$Scope
    )
    $arguments = New-Object System.Collections.Generic.List[string]
    $arguments.Add("install")
    $arguments.Add("--id")
    $arguments.Add($Id)
    $arguments.Add("--exact")
    $arguments.Add("--source")
    $arguments.Add("winget")
    $arguments.Add("--accept-package-agreements")
    $arguments.Add("--accept-source-agreements")
    $arguments.Add("--disable-interactivity")
    if (-not [string]::IsNullOrWhiteSpace($Scope)) {
        $arguments.Add("--scope")
        $arguments.Add($Scope)
    }
    return $arguments.ToArray()
}

function ConvertTo-WinToolWingetResult {
    param(
        [int]$ExitCode,
        [string]$Output
    )
    $status = "Failed"
    if ($ExitCode -eq 0) {
        $status = "Installed"
    }
    $already = $false
    if ($ExitCode -eq $script:WinToolWingetAlreadyInstalled) {
        $already = $true
    }
    if (-not [string]::IsNullOrWhiteSpace($Output) -and $Output -match '(?i)already installed|no available upgrade|no newer package version') {
        $already = $true
    }
    if ($already) {
        $status = "AlreadyInstalled"
    }
    return [pscustomobject]@{
        Status = $status
        ExitCode = $ExitCode
        Output = $Output
    }
}

function Get-WinToolAppPlan {
    param(
        $App
    )
    $steps = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($App)) {
        $name = Get-WinToolNote -Object $item -Name "Name"
        if ($null -eq $name) {
            $name = Get-WinToolNote -Object $item -Name "name" -Default "App"
        }
        $wingetId = Get-WinToolNote -Object $item -Name "WingetId"
        if ($null -eq $wingetId) {
            $wingetId = Get-WinToolNote -Object $item -Name "wingetId" -Default ""
        }
        $scope = Get-WinToolNote -Object $item -Name "Scope"
        if ($null -eq $scope) {
            $scope = Get-WinToolNote -Object $item -Name "scope" -Default ""
        }
        $steps.Add([pscustomobject]@{
            Type = "winget"
            Label = "Install $name"
            WingetId = [string]$wingetId
            Scope = [string]$scope
        })
    }
    return $steps.ToArray()
}
# endregion

# region src/Private/Process.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Invoke-WinToolCapturedProcess {
    param(
        [Parameter(Mandatory = $true)][string]$FilePath,
        [string[]]$ArgumentList
    )
    $stdout = [System.IO.Path]::GetTempFileName()
    $stderr = [System.IO.Path]::GetTempFileName()
    try {
        $process = Start-Process -FilePath $FilePath -ArgumentList (ConvertTo-WinToolArgumentLine -ArgumentList $ArgumentList) -Wait -PassThru -NoNewWindow -RedirectStandardOutput $stdout -RedirectStandardError $stderr
        $output = ""
        if (Test-Path -LiteralPath $stdout) {
            $output = [System.IO.File]::ReadAllText($stdout)
        }
        if (Test-Path -LiteralPath $stderr) {
            $errorText = [System.IO.File]::ReadAllText($stderr)
            if (-not [string]::IsNullOrWhiteSpace($errorText)) {
                $output = $output.TrimEnd() + [Environment]::NewLine + $errorText
            }
        }
        return [pscustomobject]@{
            ExitCode = [int]$process.ExitCode
            Output = $output.Trim()
        }
    }
    finally {
        Remove-Item -LiteralPath $stdout, $stderr -Force -ErrorAction SilentlyContinue
    }
}

function Start-WinToolAsyncProcess {
    param(
        [Parameter(Mandatory = $true)][string]$FilePath,
        [string[]]$ArgumentList,
        [Parameter(Mandatory = $true)]$LineQueue
    )
    $info = New-Object System.Diagnostics.ProcessStartInfo
    $info.FileName = $FilePath
    $info.Arguments = (ConvertTo-WinToolArgumentLine -ArgumentList $ArgumentList)
    $info.UseShellExecute = $false
    $info.CreateNoWindow = $true
    $info.RedirectStandardOutput = $true
    $info.RedirectStandardError = $true
    $info.StandardOutputEncoding = [System.Text.Encoding]::UTF8
    $info.StandardErrorEncoding = [System.Text.Encoding]::UTF8

    $process = New-Object System.Diagnostics.Process
    $process.StartInfo = $info
    $process.EnableRaisingEvents = $true
    $queue = $LineQueue

    $outputHandler = {
        $payload = $args[1]
        if ($null -ne $payload -and $null -ne $payload.Data) {
            $queue.Enqueue([string]$payload.Data)
        }
    }.GetNewClosure()
    $errorHandler = {
        $payload = $args[1]
        if ($null -ne $payload -and $null -ne $payload.Data) {
            $queue.Enqueue([string]$payload.Data)
        }
    }.GetNewClosure()

    $process.add_OutputDataReceived($outputHandler)
    $process.add_ErrorDataReceived($errorHandler)
    $started = $process.Start()
    if (-not $started) {
        throw "The process did not start: $FilePath"
    }
    $process.BeginOutputReadLine()
    $process.BeginErrorReadLine()
    return $process
}
# endregion

# region src/Private/Tweaks.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

function Get-WinToolTweakStep {
    param(
        [Parameter(Mandatory = $true)]$Tweak,
        [Parameter(Mandatory = $true)][ValidateSet("Apply", "Undo")][string]$Direction
    )
    $block = $null
    if ($Direction -eq "Apply") {
        $block = Get-WinToolNote -Object $Tweak -Name "apply"
    }
    else {
        $block = Get-WinToolNote -Object $Tweak -Name "undo"
    }
    $steps = New-Object System.Collections.Generic.List[object]
    if ($null -eq $block) {
        return $steps.ToArray()
    }
    Add-WinToolActionStep -Action $block -Tweak $Tweak -Steps $steps
    return $steps.ToArray()
}

function Add-WinToolActionStep {
    param(
        $Action,
        $Tweak,
        $Steps
    )
    $type = [string](Get-WinToolNote -Object $Action -Name "type" -Default "")
    if ($type -eq "group") {
        foreach ($child in @(Get-WinToolNote -Object $Action -Name "actions" -Default @())) {
            Add-WinToolActionStep -Action $child -Tweak $Tweak -Steps $Steps
        }
        return
    }
    if ($type -eq "registry") {
        foreach ($entry in @(Get-WinToolNote -Object $Action -Name "entries" -Default @())) {
            $Steps.Add([pscustomobject]@{
                Type = "registry-set"
                Path = [string](Get-WinToolNote -Object $entry -Name "path" -Default "")
                Name = [string](Get-WinToolNote -Object $entry -Name "name" -Default "")
                Value = Get-WinToolNote -Object $entry -Name "value"
                Kind = [string](Get-WinToolNote -Object $entry -Name "kind" -Default "DWord")
            })
        }
        return
    }
    if ($type -eq "registry-remove") {
        foreach ($entry in @(Get-WinToolNote -Object $Action -Name "entries" -Default @())) {
            $Steps.Add([pscustomobject]@{
                Type = "registry-remove-value"
                Path = [string](Get-WinToolNote -Object $entry -Name "path" -Default "")
                Name = [string](Get-WinToolNote -Object $entry -Name "name" -Default "")
            })
        }
        return
    }
    if ($type -eq "registry-key") {
        $Steps.Add([pscustomobject]@{
            Type = "registry-key"
            Operation = [string](Get-WinToolNote -Object $Action -Name "operation" -Default "")
            Path = [string](Get-WinToolNote -Object $Action -Name "path" -Default "")
            DefaultValue = Get-WinToolNote -Object $Action -Name "defaultValue" -Default $null
        })
        return
    }
    if ($type -eq "service") {
        $Steps.Add([pscustomobject]@{
            Type = "service"
            Name = [string](Get-WinToolNote -Object $Action -Name "name" -Default "")
            StartupType = [string](Get-WinToolNote -Object $Action -Name "startupType" -Default "Manual")
            Stop = [bool](Get-WinToolNote -Object $Action -Name "stop" -Default $false)
        })
        return
    }
    if ($type -eq "scheduled-task") {
        $Steps.Add([pscustomobject]@{
            Type = "scheduled-task"
            TaskName = [string](Get-WinToolNote -Object $Action -Name "taskName" -Default "")
            TaskPath = [string](Get-WinToolNote -Object $Action -Name "taskPath" -Default "")
            State = [string](Get-WinToolNote -Object $Action -Name "state" -Default "Enabled")
        })
        return
    }
    if ($type -eq "appx") {
        $packages = New-Object System.Collections.Generic.List[string]
        foreach ($package in @(Get-WinToolNote -Object $Action -Name "packages" -Default @())) {
            $packages.Add([string]$package)
        }
        $Steps.Add([pscustomobject]@{
            Type = "appx-remove"
            Packages = $packages.ToArray()
        })
        return
    }
    if ($type -eq "appx-restore") {
        $apply = Get-WinToolNote -Object $Tweak -Name "apply"
        $packages = New-Object System.Collections.Generic.List[string]
        foreach ($package in @(Get-WinToolNote -Object $apply -Name "packages" -Default @())) {
            $packages.Add([string]$package)
        }
        $Steps.Add([pscustomobject]@{
            Type = "appx-restore"
            Packages = $packages.ToArray()
        })
        return
    }
    throw "WinTool does not know how to run the tweak action '$type'."
}

function Get-WinToolRestorePointScript {
    $scriptText = @'
param($Sync, $Description)
$ErrorActionPreference = "Stop"
try {
    $drive = $env:SystemDrive + "\"
    Enable-ComputerRestore -Drive $drive
    $key = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore"
    $hadFrequency = $false
    $previousFrequency = 0
    if (Test-Path -LiteralPath $key) {
        $item = Get-ItemProperty -LiteralPath $key -Name "SystemRestorePointCreationFrequency" -ErrorAction SilentlyContinue
        if ($null -ne $item) {
            $hadFrequency = $true
            $previousFrequency = [int]$item.SystemRestorePointCreationFrequency
        }
    }
    else {
        New-Item -Path $key -Force | Out-Null
    }
    New-ItemProperty -LiteralPath $key -Name "SystemRestorePointCreationFrequency" -PropertyType DWord -Value 0 -Force | Out-Null
    try {
        Checkpoint-Computer -Description $Description -RestorePointType MODIFY_SETTINGS
    }
    finally {
        if ($hadFrequency) {
            New-ItemProperty -LiteralPath $key -Name "SystemRestorePointCreationFrequency" -PropertyType DWord -Value $previousFrequency -Force | Out-Null
        }
        else {
            Remove-ItemProperty -LiteralPath $key -Name "SystemRestorePointCreationFrequency" -ErrorAction SilentlyContinue
        }
    }
    $Sync.Ok = $true
}
catch {
    $Sync.Ok = $false
    $Sync.Error = $_.Exception.Message
}
$Sync.Done = $true
'@
    return $scriptText
}

function Invoke-WinToolRestorePoint {
    param(
        [string]$Description = "WinTool before tweaks"
    )
    if (-not (Test-WinToolWindows)) {
        throw "Restore points can only be created on Windows."
    }
    $sync = @{
        Done = $false
        Ok = $false
        Error = $null
    }
    $body = [scriptblock]::Create((Get-WinToolRestorePointScript))
    & $body $sync $Description
    if (-not $sync.Ok) {
        $reason = [string]$sync.Error
        if ([string]::IsNullOrWhiteSpace($reason)) {
            $reason = "No details were returned."
        }
        throw "Restore point was not created. $reason"
    }
}

function Start-WinToolRestorePointJob {
    param(
        [string]$Description = "WinTool before tweaks"
    )
    $sync = [hashtable]::Synchronized(@{
        Done = $false
        Ok = $false
        Error = $null
    })
    $runspace = [runspacefactory]::CreateRunspace()
    $runspace.ApartmentState = "STA"
    $runspace.Open()
    $powershell = [powershell]::Create()
    $powershell.Runspace = $runspace
    [void]$powershell.AddScript((Get-WinToolRestorePointScript))
    [void]$powershell.AddArgument($sync)
    [void]$powershell.AddArgument($Description)
    [void]$powershell.BeginInvoke()
    return [pscustomobject]@{
        PowerShell = $powershell
        Handle = $null
        Sync = $sync
        Runspace = $runspace
    }
}

function Stop-WinToolThread {
    param($Job)
    if ($null -eq $Job) {
        return
    }
    try { $Job.PowerShell.Stop() } catch { $null = $_.Exception.Message }
    try { $Job.PowerShell.Dispose() } catch { $null = $_.Exception.Message }
    try { $Job.Runspace.Close() } catch { $null = $_.Exception.Message }
    try { $Job.Runspace.Dispose() } catch { $null = $_.Exception.Message }
}

function Send-WinToolSettingChange {
    if (-not (Test-WinToolWindows)) {
        return
    }
    if (-not ("WinTool.NativeMethods" -as [type])) {
        Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
namespace WinTool {
    public static class NativeMethods {
        [DllImport("user32.dll", CharSet = CharSet.Auto, SetLastError = true)]
        public static extern IntPtr SendMessageTimeout(
            IntPtr hWnd, int Msg, IntPtr wParam, string lParam,
            int fuFlags, int uTimeout, out IntPtr lpdwResult);
    }
}
"@
    }
    $result = [IntPtr]::Zero
    [WinTool.NativeMethods]::SendMessageTimeout([IntPtr]0xffff, 0x001A, [IntPtr]::Zero, "ImmersiveColorSet", 2, 200, [ref]$result) | Out-Null
    [WinTool.NativeMethods]::SendMessageTimeout([IntPtr]0xffff, 0x001A, [IntPtr]::Zero, "Policy", 2, 200, [ref]$result) | Out-Null
}

function Restart-WinToolExplorer {
    if (-not (Test-WinToolWindows)) {
        return
    }
    Write-WinToolLog -Message "Restarting File Explorer so the changes show up." -Level "info"
    Stop-Process -Name "explorer" -Force -ErrorAction SilentlyContinue
}

function Invoke-WinToolTweakStep {
    param(
        [Parameter(Mandatory = $true)]$Step
    )
    if (-not (Test-WinToolWindows)) {
        throw "Tweaks can only be applied on Windows."
    }
    $type = [string]$Step.Type
    if ($type -eq "registry-set") {
        if (-not (Test-Path -LiteralPath $Step.Path)) {
            New-Item -Path $Step.Path -Force | Out-Null
        }
        if ([string]::IsNullOrEmpty([string]$Step.Name)) {
            Set-Item -LiteralPath $Step.Path -Value $Step.Value
            return
        }
        New-ItemProperty -LiteralPath $Step.Path -Name $Step.Name -Value $Step.Value -PropertyType $Step.Kind -Force | Out-Null
        return
    }
    if ($type -eq "registry-remove-value") {
        if (Test-Path -LiteralPath $Step.Path) {
            Remove-ItemProperty -LiteralPath $Step.Path -Name $Step.Name -ErrorAction SilentlyContinue
        }
        return
    }
    if ($type -eq "registry-key") {
        if ($Step.Operation -eq "remove") {
            if (Test-Path -LiteralPath $Step.Path) {
                Remove-Item -LiteralPath $Step.Path -Recurse -Force
            }
            return
        }
        if (-not (Test-Path -LiteralPath $Step.Path)) {
            New-Item -Path $Step.Path -Force | Out-Null
        }
        if ($null -ne $Step.DefaultValue) {
            Set-Item -LiteralPath $Step.Path -Value ([string]$Step.DefaultValue)
        }
        return
    }
    if ($type -eq "service") {
        $service = Get-Service -Name $Step.Name -ErrorAction SilentlyContinue
        if ($null -eq $service) {
            Write-WinToolLog -Message "Service $($Step.Name) is not on this PC. Skipped." -Level "warn"
            return
        }
        Set-Service -Name $Step.Name -StartupType $Step.StartupType
        if ($Step.Stop -and $Step.StartupType -eq "Disabled") {
            Stop-Service -Name $Step.Name -Force -ErrorAction SilentlyContinue
        }
        return
    }
    if ($type -eq "scheduled-task") {
        $task = Get-ScheduledTask -TaskName $Step.TaskName -TaskPath $Step.TaskPath -ErrorAction SilentlyContinue
        if ($null -eq $task) {
            Write-WinToolLog -Message "Scheduled task $($Step.TaskName) was not found. Skipped." -Level "warn"
            return
        }
        if ($Step.State -eq "Disabled") {
            Disable-ScheduledTask -TaskName $Step.TaskName -TaskPath $Step.TaskPath | Out-Null
        }
        else {
            Enable-ScheduledTask -TaskName $Step.TaskName -TaskPath $Step.TaskPath | Out-Null
        }
        return
    }
    if ($type -eq "appx-remove") {
        foreach ($name in @($Step.Packages)) {
            $packages = @(Get-AppxPackage -Name $name -ErrorAction SilentlyContinue)
            if ($packages.Count -eq 0) {
                Write-WinToolLog -Message "$name is not installed for this user. Skipped." -Level "info"
                continue
            }
            foreach ($package in $packages) {
                Remove-AppxPackage -Package $package.PackageFullName
                Write-WinToolLog -Message "Removed $($package.Name)." -Level "ok"
            }
        }
        return
    }
    if ($type -eq "appx-restore") {
        $provisioned = @(Get-AppxProvisionedPackage -Online)
        foreach ($name in @($Step.Packages)) {
            $match = $null
            foreach ($package in $provisioned) {
                if ([string]$package.DisplayName -eq $name) {
                    $match = $package
                    break
                }
            }
            if ($null -eq $match) {
                Write-WinToolLog -Message "Cannot restore $name because Windows no longer has a provisioned copy." -Level "warn"
                continue
            }
            $manifest = Join-Path ([string]$match.InstallLocation) "AppxManifest.xml"
            if (-not (Test-Path -LiteralPath $manifest)) {
                Write-WinToolLog -Message "Cannot restore $name because its manifest is missing." -Level "warn"
                continue
            }
            Add-AppxPackage -Register -DisableDevelopmentMode $manifest
            Write-WinToolLog -Message "Restored $name." -Level "ok"
        }
        return
    }
    throw "Unknown tweak step '$type'."
}

function Invoke-WinToolTweakChange {
    param(
        $Tweak,
        [Parameter(Mandatory = $true)][ValidateSet("Apply", "Undo")][string]$Direction,
        [bool]$RestartExplorer = $false
    )
    $needsExplorer = $false
    $needsTheme = $false
    foreach ($item in @($Tweak)) {
        $name = [string](Get-WinToolNote -Object $item -Name "name" -Default "Tweak")
        Write-WinToolLog -Message ("{0}: {1}" -f $Direction, $name) -Level "info"
        $steps = @(Get-WinToolTweakStep -Tweak $item -Direction $Direction)
        foreach ($step in $steps) {
            Invoke-WinToolTweakStep -Step $step
        }
        $refresh = [string](Get-WinToolNote -Object $item -Name "refresh" -Default "none")
        if ($refresh -eq "explorer") {
            $needsExplorer = $true
        }
        if ($refresh -eq "theme") {
            $needsTheme = $true
        }
    }
    if ($needsTheme) {
        Send-WinToolSettingChange
    }
    if ($needsExplorer -and $RestartExplorer) {
        Restart-WinToolExplorer
    }
}
# endregion

